<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetAllowController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetListController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetCreateController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetRetrieveController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetUpdateController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetDeleteController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetEnableController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetDisableController;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest\SnippetAssetTempContentUploadController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Service\Visibility\SnippetAssetRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driven\SnippetAssetReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driven\SnippetAssetWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetReadGateway;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetWriteGateway;

class SnippetAssetPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[SnippetAssetReadGateway::class] = \DI\autowire(SnippetAssetReadRepositoryAdapter::class);
        $def[SnippetAssetWriteGateway::class] = \DI\autowire(SnippetAssetWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/snippet-asset', [$this, 'setRoutesForSnippetAsset']);
        $collector->group('/api/me/acl/document/snippet-asset', [$this, 'setRoutesForSnippetAssetAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(SnippetAssetRestrictFilterToVisibility::class, TenantAccesible::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("snippet-asset", "list", "READ");
            $handler->registerResourceAction("snippet-asset", "create", "WRITE");
            $handler->registerResourceAction("snippet-asset", "retrieve", "READ");
            $handler->registerResourceAction("snippet-asset", "update", "WRITE");
            $handler->registerResourceAction("snippet-asset", "delete", "WRITE");
            $handler->registerResourceAction("snippet-asset", "enable", "WRITE");
            $handler->registerResourceAction("snippet-asset", "disable", "WRITE");

            $handler->registerResourceAttribute("snippet-asset", "snippet", "MANAGE");
            $handler->registerResourceAttribute("snippet-asset", "code", "MANAGE");
            $handler->registerResourceAttribute("snippet-asset", "type", "MANAGE");
            $handler->registerResourceAttribute("snippet-asset", "content", "MANAGE");
            $handler->registerResourceAttribute("snippet-asset", "enabled", "MANAGE");
            $handler->registerResourceAttribute("snippet-asset", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForSnippetAssetAcl(RouteCollectorProxy $snippetAssetGroup): void
    {
        $snippetAssetGroup->get('', [SnippetAssetAllowController::class, 'genericAllow']);
        $snippetAssetGroup->get('/{uid}', [SnippetAssetAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForSnippetAsset(RouteCollectorProxy $snippetAssetGroup): void
    {
        $snippetAssetGroup->get('', [SnippetAssetListController::class, 'list']);
        $snippetAssetGroup->post('', [SnippetAssetCreateController::class, 'create']);
        $snippetAssetGroup->get('/{uid}', [SnippetAssetRetrieveController::class, 'retrieve']);
        $snippetAssetGroup->get('/{uid}/content', [SnippetAssetRetrieveController::class, 'retrieveContent']);
        $snippetAssetGroup->put('/{uid}', [SnippetAssetUpdateController::class, 'update']);
        $snippetAssetGroup->delete('/{uid}', [SnippetAssetDeleteController::class, 'delete']);
        $snippetAssetGroup->delete('', [SnippetAssetDeleteController::class, 'deleteAllForQuery']);
        $snippetAssetGroup->get('/~/delete-status/{uid}', [SnippetAssetDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $snippetAssetGroup->patch('/~/enable', [SnippetAssetEnableController::class, 'enableAllForQuery']);
        $snippetAssetGroup->patch('/{uid}/enable', [SnippetAssetEnableController::class, 'enable']);
        $snippetAssetGroup->get('/~/enable-status/{uid}', [SnippetAssetEnableController::class, 'checkEnableAllForQueryStatus']);
        $snippetAssetGroup->patch('/~/disable', [SnippetAssetDisableController::class, 'disableAllForQuery']);
        $snippetAssetGroup->patch('/{uid}/disable', [SnippetAssetDisableController::class, 'disable']);
        $snippetAssetGroup->get('/~/disable-status/{uid}', [SnippetAssetDisableController::class, 'checkDisableAllForQueryStatus']);
        $snippetAssetGroup->post('/-/temp-content', [SnippetAssetTempContentUploadController::class, 'uploadTemp']);
        $snippetAssetGroup->get('/-/temp-content', [SnippetAssetTempContentUploadController::class, 'getTemp']);
    }
}
